const userId = $json.jwtPayload?.userId;
if (!userId) return [{ json: { __error: true, __code: 401, __message: 'Token sin userId' } }];

const q = $json.query || {};
const COLUMNS = ["draft","new","unscheduled","partially_scheduled","scheduled","in_progress","completed","cancelled"];
// Cuántas tarjetas por columna. "Cargar más" pide una sola columna con `column` y `offset`.
const limit = Math.min(200, Math.max(1, parseInt(q.limit, 10) || 25));
const column = COLUMNS.includes(q.column) ? q.column : '';
const offset = column ? Math.max(0, parseInt(q.offset, 10) || 0) : 0;

const filters = {
  scope: ['clinic', 'patient'].includes(q.scope) ? q.scope : 'mine',
  search: (q.q || '').trim(),
  sede_id: q.sede_id || '',
  source: ['portal', 'whatsapp'].includes(q.source) ? q.source : '',
  patient_id: q.patient_id || '',
  doctor_id: q.doctor_id || '',
  // Responsable: 'me' (asignadas a quien consulta), 'none' (sin asignar) o el id de un usuario.
  assigned: ['me', 'none'].includes(q.assigned) || /^[0-9a-f-]{36}$/i.test(q.assigned || '') ? q.assigned : '',
  sla_hours: Number(q.sla_hours) > 0 ? Number(q.sla_hours) : 48,
  date_from: q.date_from || '',
  date_to: q.date_to || '',
  column,
  limit,
  offset,
};

return [{ json: { user_id: String(userId), filters: JSON.stringify(filters), limit, column, offset } }];

// Arma el sobre { code, message, data, meta }. Un resultado vacío en una
// operación de escritura significa que el WHERE de guarda no dejó pasar:
// es un 409/404, no un 500.
//
// El filtro descarta el item vacio que emite el nodo de Postgres cuando la
// consulta no devuelve filas (lleva alwaysOutputData para que el flujo llegue a
// responder). Sin el, ese {} se colaria como si fuera una fila real: un detalle
// de orden vacio en vez de un 404, o un listado con un elemento fantasma.
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);

const input = $('Validar Datos').first().json;
return [{ json: {
  __data: rows[0]?.columns ?? [],
  __meta: { limit: input.limit, column: input.column || null, offset: input.offset },
} }];
